import {observationMessage} from './shared-messages.mjs';
import {environmentMessage} from '../environment/messages.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=key=>observationMessage(key,I18n.language),number=(value,digits=3)=>Number.isFinite(value)?new Intl.NumberFormat(I18n.locale,{maximumFractionDigits:digits}).format(value):t('unknown');
const facts=rows=>'<dl class="environment-facts">'+rows.map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(value??t('unknown'))}</dd></div>`).join('')+'</dl>';
const contextLabel=result=>result?.status==='available'?number(result.vector?.speed??result.value)+' '+(result.units||''):t('unavailable');
export class SharedObservationController{
  constructor(container,repository,service,{openPanel=()=>{},onChange=()=>{}}={}){
    Object.assign(this,{container,repository,service,openPanel,onChange,map:null,group:null,manifest:null,records:[],selected:null,context:null,busy:false,error:false,activated:false,generation:0,page:0,filters:{speciesId:'megaptera-novaeangliae',year:'2025',month:'all',source:'all',recordType:'all',presence:'all',certainty:'all',show:true}});
    container.dataset.userContent='';
    container.addEventListener('change',event=>{const key=event.target.dataset.sharedObservationFilter;if(!key)return;this.filters[key]=event.target.type==='checkbox'?event.target.checked:event.target.value;this.page=0;this.selected=null;this.context=null;if(key==='show'){this.render();return;}this.refresh();});
    container.addEventListener('click',event=>{const button=event.target.closest('[data-shared-observation-action]'),pick=event.target.closest('[data-shared-observation-id]');if(pick){this.select(this.records.find(r=>r.id===pick.dataset.sharedObservationId));return;}if(!button)return;const action=button.dataset.sharedObservationAction;if(action==='fit')this.fit();if(action==='retry')this.activate(true);if(action==='next'){this.page++;this.render();}if(action==='previous'){this.page=Math.max(0,this.page-1);this.render();}if(action==='context')this.queryContext();});
    this.render();
  }
  async restore(){try{this.manifest=await this.repository.open();this.error=false;this.render();this.onChange();}catch{this.error=true;this.render();}}
  async activate(force=false){if(!this.activated||force){this.activated=true;if(!this.manifest)await this.restore();if(this.manifest)await this.refresh();}}
  attachMap(map){if(this.map===map)return;this.map=map;map.createPane('sharedObservationsPane').style.zIndex=465;this.renderer=window.L.canvas({pane:'sharedObservationsPane',padding:.1});map.on('moveend zoomend',()=>{if(!this.queued){this.queued=true;requestAnimationFrame(()=>{this.queued=false;this.draw();});}});this.draw();}
  async refresh(){
    const generation=++this.generation;this.busy=true;this.error=false;this.records=[];this.selected=null;this.context=null;this.render();
    try{const result=await this.service.query(this.filters);if(generation!==this.generation)return;if(!['available','no_observations_for_query'].includes(result.status))throw Error(result.status);this.records=result.records;this.result=result;}
    catch{if(generation===this.generation)this.error=true;}
    finally{if(generation===this.generation){this.busy=false;this.render();}}
  }
  render(){
    const m=this.manifest,f=this.filters,species=m?.species.find(s=>s.id===f.speciesId),years=[...(species?.years||[])],count=this.records.length;if(f.year!=='all'&&!years.includes(f.year))years.push(f.year);years.sort();
    this.page=Math.min(this.page,Math.max(0,Math.ceil(count/8)-1));
    const select=(key,options)=>`<select data-shared-observation-filter="${key}" ${this.busy?'disabled':''}>${options.map(([value,label])=>`<option value="${esc(value)}" ${String(f[key])===String(value)?'selected':''}>${esc(label)}</option>`).join('')}</select>`;
    this.container.innerHTML=`<div class="observation-intro"><span class="workbench-tag">${esc(t('ready'))}</span><h3>${esc(t('title'))}</h3><p>${esc(t('intro'))}</p></div>${this.error?`<p role="status" class="environment-query-warning">${esc(t('error'))}</p><button class="btn secondary full" data-shared-observation-action="retry">${esc(t('retry'))}</button>`:''}${m?`
      <label>${esc(t('species'))}${select('speciesId',m.species.map(s=>[s.id,s.scientificName]))}</label>
      <div class="observation-filters"><label>${esc(t('year'))}${select('year',[['all',t('all')],...years.slice().reverse().map(y=>[y,y==='unknown'?t('unknownYear'):y])])}</label><label>${esc(t('month'))}${select('month',[['all',t('all')],...Array.from({length:12},(_,i)=>[String(i+1),new Intl.DateTimeFormat(I18n.locale,{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2025,i,1)))])])}</label></div>
      <label>${esc(t('source'))}${select('source',[['all',t('all')],['obis','OBIS-SEAMAP · CC0'],['noaa','NOAA · RWSAS']])}</label>
      <details class="environment-notes shared-quality-controls"><summary>${esc(t('type'))}</summary><label>${esc(t('type'))}${select('recordType',[['all',t('all')],...['ptobs','ptphoto','pttag','ptacs_pa','ptacs_calls'].map(k=>[k,t(k)])])}</label><label>${esc(t('reported')+' / '+t('absence'))}${select('presence',[['all',t('all')],['reported',t('reported')],['absence',t('absence')]])}</label><label>${esc(t('certainty'))}${select('certainty',[['all',t('all')],['Definite','Definite'],['Probable','Probable'],['not_provided',t('unknown')]])}</label></details>
      <div class="observation-summary" role="status"><div><strong>${number(species?.recordCount,0)}</strong><span>${esc(t('events'))}</span></div><div><strong>${this.busy?'…':number(count,0)}</strong><span>${esc(t('matched'))}</span></div></div>
      <label class="environment-checkbox"><input type="checkbox" data-shared-observation-filter="show" ${f.show?'checked':''}><span>${esc(t('show'))}</span></label><button class="btn secondary full" data-shared-observation-action="fit" ${!count||this.busy?'disabled':''}>${esc(t('fit'))}</button>
      <p class="small-note shared-observation-caution">${esc(t('notice'))}</p><p class="shared-observation-legend small-note">${esc(t('legend'))}</p>
      ${this.busy?`<p role="status">${esc(t('loading'))}</p>`:!count&&!this.error&&this.activated?`<p role="status">${esc(t('noMatches'))}</p>`:''}
      ${this.selected?this.selectionHTML(this.selected):''}
      <div class="shared-observation-list">${this.records.slice(this.page*8,this.page*8+8).map(r=>`<button class="observation-row" data-shared-observation-id="${esc(r.id)}"><span>${esc(r.time.display||t('unknownYear'))}<small>${number(r.lat)} / ${number(r.lon)} · ${esc(t(r.recordType))}${r.presence==='absence'?' · '+esc(t('absence')):''}</small></span><span>${esc(this.service.source(r)?.family==='noaa'?'NOAA':'CC0')} ↗</span></button>`).join('')}</div>
      ${count>8?`<div class="observation-pagination"><button class="text-link" data-shared-observation-action="previous" aria-label="${esc(t('previous'))}" ${this.page?'':'disabled'}>←</button><span>${this.page*8+1}–${Math.min(count,this.page*8+8)} / ${number(count,0)}</span><button class="text-link" data-shared-observation-action="next" aria-label="${esc(t('next'))}" ${(this.page+1)*8<count?'':'disabled'}>→</button></div>`:''}
      ${this.auditHTML(m)}`:''}`;
    this.draw();
    const badge=document.getElementById('observationOverlayBadge');if(badge){badge.hidden=!f.show||!count||this.busy||this.error;badge.textContent=t('title')+' · '+(species?.scientificName?.replace(/^([A-Z])[a-z]+ /,'$1. ')||'')+' · '+(f.year==='all'?t('all'):f.year)+(f.month==='all'?'':'-'+String(f.month).padStart(2,'0'))+' · '+number(count,0);}
    const summary=document.querySelector('#localObservationDisclosure>summary');if(summary)summary.textContent=t('local');
  }
  auditHTML(m){return `<details class="environment-notes shared-observation-audit"><summary>${esc(t('details'))}</summary>${facts([[t('auditRows'),number(m.rawRecordsRead,0)],[t('publicRows'),number(m.recordCount,0)],[t('excluded'),number(m.rawRecordsRead-m.recordCount,0)]])}<p>${esc(t('rights'))}</p><p>${esc(t('auditNote'))}</p><p>${esc(t('snapshot'))}</p><p>${esc(t('observerPosition'))}</p><p>${esc(t('overlap'))}</p><p>${esc(t('precisionNote'))}</p><p>${esc(t('timezoneNote'))}</p><table><thead><tr><th>${esc(t('archive'))}</th><th>${esc(t('read'))}</th><th>${esc(t('published'))}</th></tr></thead><tbody>${m.audits.map(a=>`<tr><td>${esc(a.speciesId==='balaenoptera-physalus'?'B. physalus':a.speciesId==='balaenoptera-musculus'?'B. musculus':a.speciesId==='megaptera-novaeangliae'?'M. novaeangliae':a.file.endsWith('.csv')?'NOAA RWSAS':'E. glacialis')}</td><td>${number(a.rowsRead,0)}</td><td>${number(a.publishedRows,0)}</td></tr>`).join('')}</tbody></table><p>${esc(m.collectionCitation)}</p><a href="https://seamap.env.duke.edu/content/content/termsofuse" target="_blank" rel="noopener">OBIS-SEAMAP · ${esc(t('license'))} ↗</a><br><a href="https://www.fisheries.noaa.gov/inport/item/23305" target="_blank" rel="noopener">NOAA RWSAS · ${esc(t('source'))} ↗</a></details>`;}
  selectionHTML(r){const source=this.service.source(r);return `<div class="observation-selection shared-observation-selection"><h3>${esc(t('selected'))}</h3><p><i>${esc(this.manifest.species.find(s=>s.id===r.speciesId)?.scientificName)}</i></p>${facts([[t('date'),r.time.display||t('unknownYear')],[t('precision'),t(r.time.precision)],[t('type'),t(r.recordType)],[t('presence'),t(r.presence)],[t('source'),source?.title],[t('license'),source?.license],[t('uncertainty'),r.uncertaintyMeters==null?t('unknown'):number(r.uncertaintyMeters)+' m'],[t('digits'),number(r.coordinateDecimalDigits,0)],[t('group'),number(r.groupSize)],[t('certainty'),r.certainty||t('unknown')],['ID',r.rowId]])}<p>${esc(t('precisionNote'))}</p><p>${esc(t('timezoneNote'))}</p><p class="small-note">${esc(source?.citation)}</p><a href="${esc(source?.url)}" target="_blank" rel="noopener">${esc(t('source'))} ↗</a>${source?.family==='noaa'?`<p>${esc(t('snapshot'))}</p><p>${esc(t('observerPosition'))}</p>`:''}<button class="btn secondary full" data-shared-observation-action="context" ${r.time.date?'':'disabled'}>${esc(t('context'))}</button>${r.time.date?'':`<p>${esc(t('exactDayMissing'))}</p>`}<p class="small-note">${esc(t('contextNote'))}</p>${this.contextHTML()}</div>`;}
  contextHTML(){if(!this.context)return '';if(this.context==='loading')return `<p role="status">${esc(t('loading'))}</p>`;if(this.context.status!=='queried')return `<p role="status">${esc(t('unavailable'))}</p>`;return `<div class="observation-environment-context" role="status">${[['sst',environmentMessage('sst',I18n.language)],['current',environmentMessage('current_speed',I18n.language)]].map(([key,label])=>{const r=this.context[key];return `<div><strong>${esc(label==='current_speed'?'Copernicus · m/s':label)}</strong><span>${esc(contextLabel(r))}</span><small>${esc(r?.time||this.context.queryDate)}</small><details class="environment-result-source"><summary>${esc(t('details'))}</summary>${facts([[t('source'),r?.source?.originalFile],[t('date'),r?.time],[t('uncertainty'),r?.uncertainty?.value==null?t('unknown'):number(r.uncertainty.value)+' '+r.uncertainty.units],['Status',r?.status]])}</details></div>`;}).join('')}</div>`;}
  async queryContext(){const record=this.selected;if(!record)return;const generation=++this.generation;this.context='loading';this.render();try{const result=await this.service.environmentalContext(record);if(generation===this.generation&&this.selected===record)this.context=result;}catch{if(generation===this.generation)this.context={status:'error'};}if(generation===this.generation)this.render();}
  select(record){if(!record)return;++this.generation;this.selected=record;this.context=null;this.openPanel('observations');this.render();this.container.querySelector('.shared-observation-selection')?.scrollIntoView({block:'nearest',behavior:'instant'});}
  fit(){if(!this.map||!this.records.length)return;this.filters.show=true;this.map.fitBounds(window.L.latLngBounds(this.records.map(r=>[r.lat,r.lon])),{maxZoom:8,padding:[45,45]});this.render();}
  draw(){if(!this.map)return;const L=window.L;if(this.group)this.map.removeLayer(this.group);this.group=null;const credit='OBIS-SEAMAP · CC0 / NOAA RWSAS';if(this.creditShown){this.map.attributionControl.removeAttribution(credit);this.creditShown=false;}if(!this.filters.show||!this.records.length||this.busy||this.error)return;this.group=L.layerGroup().addTo(this.map);this.map.attributionControl.addAttribution(credit);this.creditShown=true;
    const cells=new Map(),bounds=this.map.getBounds().pad(.1);for(const r of this.records){if(!bounds.contains([r.lat,r.lon]))continue;const p=this.map.latLngToContainerPoint([r.lat,r.lon]),key=Math.floor(p.x/29)+':'+Math.floor(p.y/29);if(!cells.has(key))cells.set(key,[]);cells.get(key).push(r);}
    for(const records of cells.values()){const r=records[0],marker=records.length===1?L.circleMarker([r.lat,r.lon],{pane:'sharedObservationsPane',radius:5,weight:1.5,color:'#fff',fillColor:r.presence==='absence'?'#8496a0':r.recordType.startsWith('ptacs')?'#8b6d9c':r.sourceId==='noaa:rwsas'?'#a87348':'#1a657b',fillOpacity:.95,bubblingMouseEvents:false,renderer:this.renderer}):L.marker([r.lat,r.lon],{pane:'sharedObservationsPane',bubblingMouseEvents:false,icon:L.divIcon({className:'observation-cluster',html:String(records.length),iconSize:[29,29],iconAnchor:[14,14]})});const tip=document.createElement('span');tip.textContent=records.length>1?number(records.length,0)+' '+t('events'):(r.time.display||t('unknownYear'))+' · '+t(r.recordType)+(r.presence==='absence'?' · '+t('absence'):'');marker.bindTooltip(tip);marker.on('click',()=>{if(records.length>1&&this.map.getZoom()<9){this.map.setView([r.lat,r.lon],this.map.getZoom()+2);return;}this.select(r);});marker.addTo(this.group);}
  }
}
